paramsDict = {}
if value['filter']['showNavItems'] is not None: paramsDict['enabled'] = value['filter']['showNavItems']

mapping = {'enableKanoaCMMS': 'kanoaCMMS', 'enableKanoaQDS': 'kanoaQDS', 'enableKanoaTrace': 'kanoaTrace', 'enableKanoaInv': 'kanoaInv'}
modules = [mapping[k] for k, v in value['configInfo'].items() if v == '1' and k in mapping]
modules += ['kanoaOPS', None]

paramsDict['modules'] = modules
navItems = system.kanoa.utilities.convertDatasetToJSON(system.kanoa.config.getNavigation(paramsDict))

reservedNavPaths = [navItem['path'] for navItem in navItems if navItem['viewPath'] in (self.custom.reservedNavItems)]	
for navItem in navItems:
	if len(reservedNavPaths) == 0: navItem['reserved'] = False
	else: navItem['reserved'] = any(p == navItem['path'] or p.startswith(navItem['path'] + '\\') for p in reservedNavPaths)

return system.kanoa.utilities.convertDictListToDataset(navItems)

customMethods.script:
system.perspective.print("save() called")
userId = self.view.custom.security.userId
navInfo = dict(self.view.custom.navInfo)

if navInfo['id'] is None and (navInfo['name'] or None) is None: return
if navInfo['roles']: navInfo['roles'] = system.util.jsonEncode(navInfo['roles'])
if navInfo['project']: navInfo['project'] = system.util.jsonEncode(navInfo['project'])

if navInfo['id']: retVal, msg = system.kanoa.config.updateNavigationItem(navInfo, userId)
else: id, msg = system.kanoa.config.addNavigationItem(navInfo, userId)

if msg: system.perspective.sendMessage('showWarningToast', {'message': "Couldn't save changes to navigation item. %s"%msg})
else: system.perspective.sendMessage('showSuccessfulToast', {'message': 'Change saved'})

self.view.refreshBinding("custom.navInfo")
self.view.refreshBinding("custom.navItems")

system.perspective.sendMessage('refreshNavigation', {})	#Tells the navigation dock view to update itself

return

